using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) GetTypeInfo<T>() — returns a strongly-typed JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) TryGetTypeInfo<T>() — probe without throwing
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded → {info!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Person> failed (unexpected)");

// Now try a type the resolver can handle but demonstrates the pattern:
// use a source-gen context that only knows about Person, so int[] is unknown.
var strict = new JsonSerializerOptions { TypeInfoResolver = PersonContext.Default };

if (strict.TryGetTypeInfo<int[]>(out JsonTypeInfo<int[]>? arrInfo))
    Console.WriteLine($"TryGetTypeInfo<int[]> succeeded → {arrInfo!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<int[]> → not available (expected)");

// Records & source-gen context
public record Person(string Name, int Age);

[JsonSerializable(typeof(Person))]
public partial class PersonContext : JsonSerializerContext;

